20	/** A collection of assorted utility classes. */
21	public final class Util {
22	  private static final int HASH_MULTIPLIER = 31;
23	  private static final int HASH_ACCUMULATOR = 17;
24	  private static final char[] HEX_CHAR_ARRAY = "0123456789abcdef".toCharArray();
25	  // 32 bytes from sha-256 -> 64 hex chars.
26	  private static final char[] SHA_256_CHARS = new char[64];
27	  @Nullable private static volatile Handler mainThreadHandler;
28	
29	  private Util() {
30	    // Utility class.
31	  }
32	
33	  /** Returns the hex string of the given byte array representing a SHA256 hash. */
34	  @NonNull
35	  public static String sha256BytesToHex(@NonNull byte[] bytes) {
36	    synchronized (SHA_256_CHARS) {
37	      return bytesToHex(bytes, SHA_256_CHARS);
38	    }
39	  }
40	
41	  // Taken from:
42	  // http://stackoverflow.com/questions/9655181/convert-from-byte-array-to-hex-string-in-java
43	  // /9655275#9655275
44	  @SuppressWarnings("PMD.UseVarargs")
45	  @NonNull
46	  private static String bytesToHex(@NonNull byte[] bytes, @NonNull char[] hexChars) {
47	    int v;
48	    for (int j = 0; j < bytes.length; j++) {
49	      v = bytes[j] & 0xFF;
50	      hexChars[j * 2] = HEX_CHAR_ARRAY[v >>> 4];
51	      hexChars[j * 2 + 1] = HEX_CHAR_ARRAY[v & 0x0F];
52	    }
53	    return new String(hexChars);
54	  }
55	
56	  /**
57	   * Returns the allocated byte size of the given bitmap.
58	   *
59	   * @see #getBitmapByteSize(android.graphics.Bitmap)
60	   * @deprecated Use {@link #getBitmapByteSize(android.graphics.Bitmap)} instead. Scheduled to be
61	   *     removed in Glide 4.0.
62	   */
63	  @Deprecated
64	  public static int getSize(@NonNull Bitmap bitmap) {
65	    return getBitmapByteSize(bitmap);
66	  }
67	
68	  /** Returns the in memory size of the given {@link Bitmap} in bytes. */
69	  @TargetApi(Build.VERSION_CODES.KITKAT)
70	  public static int getBitmapByteSize(@NonNull Bitmap bitmap) {
71	    // The return value of getAllocationByteCount silently changes for recycled bitmaps from the
72	    // internal buffer size to row bytes * height. To avoid random inconsistencies in caches, we
73	    // instead assert here.
74	    if (bitmap.isRecycled()) {
75	      throw new IllegalStateException(
76	          "Cannot obtain size for recycled Bitmap: "
77	              + bitmap
78	              + "["
79	              + bitmap.getWidth()
80	              + "x"
81	              + bitmap.getHeight()
82	              + "] "
83	              + bitmap.getConfig());
